# 8-connected component sizes for each nonbg color
for val in (3,5,9):
 seen=set(); sizes=[]
 for i,row in enumerate(grid):
  for j,v in enumerate(row):
   if v!=val or (i,j) in seen: continue
   st=[(i,j)];seen.add((i,j));n=0
   while st:
    x,y=st.pop();n+=1
    for a in range(max(0,x-1),min(len(grid),x+2)):
     for b in range(max(0,y-1),min(len(row),y+2)):
      if grid[a][b]==val and (a,b) not in seen:seen.add((a,b));st.append((a,b))
   sizes.append(n)
 print(val,sorted(sizes,reverse=True))

def comps8(val):
 seen=set(); out=[]
 for i,row in enumerate(grid):
